import{_ as a,V as i,W as e,X as n,Y as t}from"./framework-9a29aaa0.js";const r={},s=n("ul",null,[n("li",null,[n("a",{href:"#frangipani%E4%B8%80%E7%A7%8D%E5%8F%AF%E6%89%A9%E5%B1%95%E7%9A%84%E5%88%86%E5%B8%83%E5%BC%8F%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F"},"Frangipani：一种可扩展的分布式文件系统")])],-1),l=n("h1",{id:"frangipani-一种可扩展的分布式文件系统",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#frangipani-一种可扩展的分布式文件系统","aria-hidden":"true"},"#"),t(" Frangipani：一种可扩展的分布式文件系统")],-1),o=n("p",null,"理想的分布式文件系统将为其所有用户提供对同一组文件的一致、共享访问，同时还能够任意扩展，以便为不断增长的用户群体提供更多的存储空间和更高的性能。尽管存在组件故障，它也应具有高可用性。它需要最少的人工管理，并且随着更多组件的添加，管理不会变得更加复杂。",-1),_=n("p",null,"Frangipani 是一种新的文件系统，它接近这个理想状态，然而由于其两层结构，相对容易构建。底层是 Petal（在早期的一篇论文中有描述），这是一种分布式存储服务，提供可增量扩展、高可用性、自动管理的虚拟磁盘。在高层，多台机器在共享的 Petal 虚拟磁盘之上运行相同的 Frangipani 文件系统代码，并使用分布式锁服务来确保一致性。",-1),c=n("p",null,"Frangipani 旨在在一组处于共同管理下且能够安全通信的机器集群中运行。因此，这些机器相互信任，共享虚拟磁盘的方法是可行的。当然，Frangipani 文件系统可以使用普通的网络文件访问协议导出到不受信任的机器上。",-1),p=n("p",null,"我们在一组运行 DIGITAL Unix 4.0 的 Alpha 机器上实现了 Frangipani。初步测量表明，Frangipani 具有出色的单服务器性能，并且随着服务器的增加，扩展性良好。",-1),d=[s,l,o,_,c,p];function h(B,E){return i(),e("div",null,d)}const g=a(r,[["render",h],["__file","lesson11-frangipani.html.vue"]]);export{g as default};
